#!/usr/bin/env node
/*
 * Sync the OGIAM Agent Constitution from its canonical home in AgenticQA-core
 * into a committed TS module apex can bundle on Vercel.
 *
 * WHY a codegen step and not a runtime read: the canonical constitution lives
 * in a sibling repo (AgenticQA-core) which is NOT present in apex's Vercel
 * build. So we generate src/lib/constitution/generated.ts at dev time and
 * commit it. This keeps a single source of truth (edit the constitution in
 * AgenticQA-core, run this script, commit the regenerated file) while matching
 * how every other prompt in this repo is a bundled string literal.
 *
 * DRY: this is the codified process. Do not hand-edit generated.ts.
 *
 * Usage:
 *   node scripts/sync-constitution.mjs            # writes generated.ts
 *   node scripts/sync-constitution.mjs --check    # exit 1 if out of sync
 *   OGIAM_CONSTITUTION_DIR=/path node scripts/sync-constitution.mjs
 */

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const APEX_ROOT = resolve(__dirname, "..");

// Canonical source: AgenticQA-core sibling repo. Override with the env var when
// the checkout lives elsewhere.
const SRC_DIR =
  process.env.OGIAM_CONSTITUTION_DIR ||
  resolve(APEX_ROOT, "..", "AgenticQA-core", "agenticqa_core", "constitution");

const OUT = join(APEX_ROOT, "src", "lib", "constitution", "generated.ts");

function build() {
  const md = readFileSync(join(SRC_DIR, "AGENTS.md"), "utf-8");
  const version = readFileSync(join(SRC_DIR, "VERSION"), "utf-8").trim();
  // JSON.stringify makes a safe JS string literal regardless of backticks,
  // ${...} sequences, or newlines in the markdown.
  return (
    "// AUTO-GENERATED by scripts/sync-constitution.mjs from the canonical OGIAM\n" +
    "// Agent Constitution in AgenticQA-core (agenticqa_core/constitution).\n" +
    "// DO NOT EDIT BY HAND. Run `node scripts/sync-constitution.mjs` to refresh.\n\n" +
    `export const CONSTITUTION_VERSION = ${JSON.stringify(version)};\n\n` +
    `export const CONSTITUTION_MARKDOWN = ${JSON.stringify(md)};\n`
  );
}

function main() {
  if (!existsSync(SRC_DIR)) {
    console.error(
      `[sync-constitution] canonical source not found at ${SRC_DIR}.\n` +
        `Set OGIAM_CONSTITUTION_DIR to the AgenticQA-core constitution dir.`,
    );
    process.exit(2);
  }
  const next = build();
  const check = process.argv.includes("--check");
  const current = existsSync(OUT) ? readFileSync(OUT, "utf-8") : "";
  if (check) {
    if (current !== next) {
      console.error(
        "[sync-constitution] generated.ts is OUT OF SYNC with AgenticQA-core. " +
          "Run: node scripts/sync-constitution.mjs",
      );
      process.exit(1);
    }
    console.log("[sync-constitution] in sync.");
    return;
  }
  writeFileSync(OUT, next, "utf-8");
  console.log(`[sync-constitution] wrote ${OUT}`);
}

main();
